-- Harrier Central defect sweep, history repair (2026-11-27). Refs #2944 #2945 #2946
-- #2964 #2965 #2866 #3060 #2981 #3021 #3116 #3071 #3012 #2959.
--
-- HC's getEvents is future-only, so a run keeps whatever the adapter (or a one-shot
-- backfill) wrote while it was upcoming. The adapter fixes in this PR reach upcoming
-- runs only; this brings stored runs in line, from the hashruns.org global-runs archive
-- (all kennels, 2015 to today, read 2026-11-27), with the adapter's own helpers.
--
-- 1. One UPDATE over 3270 rows keyed by Event id. Generated against a 2026-11-24 copy of
--    prod; only events with a HARRIER_CENTRAL RawEvent were considered. Every field is
--    guarded, so a row that changed since is left alone and a re-run is a no-op:
--    - fill only where NULL: description (1884; PII-scrubbed, capped at 2000,
--      placeholder notes dropped), locationStreet (656; "street, postcode", only when
--      locationName doesn't already name the street), cost (2953; member price in HC's
--      currency template, a price of 0 skipped);
--    - runNumber -> NULL (59) on uncounted runs (IsCountedRun 0: parties, drinking
--      practices, weekends) that reuse a counted run's number, on events no other source feeds;
--    - title (78), only where HC supplied the stored title: line breaks and doubled
--      spaces collapsed, bare-number titles ("2360") -> "<defaultTitle> #N";
--    - startTime 00:00 -> NULL (2; HC's "no time set"), dateUtc back to the date.
-- 2. Hand corrections, each guarded by the value it replaces: DA2B fields entered in the
--    wrong HC slot (#2945), Manchester's 22 Aug title and 10 -> 11 Oct date (#3012, the
--    kennel's own Past R*ns page), Barbados anniversary titles (#3021), and the per-run
--    hashruns.org link on the three uncounted runs that carry one (#3116).
-- 3. Divahhh's schedule header (#2959): day and time vary, so clear the Saturday 3 PM.
BEGIN;
SET LOCAL lock_timeout = '5s';

UPDATE "Event" e SET
  "description"    = COALESCE(e."description", v.description),
  "locationStreet" = COALESCE(e."locationStreet", v.street),
  "cost"           = COALESCE(e."cost", v.cost),
  "runNumber"      = CASE WHEN e."runNumber" = v.clear_run THEN NULL ELSE e."runNumber" END,
  "title"          = CASE WHEN e."title" = v.old_title THEN v.title ELSE e."title" END,
  "startTime"      = CASE WHEN v.clear_time AND e."startTime" = '00:00' THEN NULL ELSE e."startTime" END,
  "dateUtc"        = CASE WHEN v.clear_time AND e."startTime" = '00:00' THEN e."date" ELSE e."dateUtc" END,
  "updatedAt"      = NOW() AT TIME ZONE 'UTC'
FROM jsonb_to_recordset(
