) AS v(
  id text, description text, street text, cost text, clear_run integer,
  old_title text, title text, clear_time boolean
)
WHERE e."id" = v.id
  AND ((v.description IS NOT NULL AND e."description" IS NULL)
    OR (v.street IS NOT NULL AND e."locationStreet" IS NULL)
    OR (v.cost IS NOT NULL AND e."cost" IS NULL)
    OR e."runNumber" = v.clear_run
    OR e."title" = v.old_title
    OR (v.clear_time AND e."startTime" = '00:00'));

