UPDATE "Event" SET "title" = 'R*n 291 - Loud and Proud', "updatedAt" = NOW() AT TIME ZONE 'UTC'
WHERE id = 'cmsze1qfc002204if0kk24taa' AND "title" = 'R*n 291 - Some Beans';

-- #3012 Manchester: R*n 294 "45 Years?" was Sunday 11 Oct (kennel site, 2nd-Sunday run), not Saturday 10th.
-- 14:00 BST is 13:00 UTC.
UPDATE "Event" e SET
  "date" = TIMESTAMP '2026-10-11 12:00:00',
  "dateUtc" = TIMESTAMP '2026-10-11 13:00:00',
  "updatedAt" = NOW() AT TIME ZONE 'UTC'
WHERE e.id = 'cmv09i6yw003004jklttcjvh9' AND e."date" = TIMESTAMP '2026-10-10 12:00:00' AND e."startTime" = '14:00'
  AND NOT EXISTS (
    SELECT 1 FROM "Event" o
    WHERE o."kennelId" = e."kennelId" AND o."date" = TIMESTAMP '2026-10-11 12:00:00' AND o."isCanonical"
  );

-- #3021 Barbados: the 41st-anniversary events had no run number, so their bare-number
-- titles can't become "Barbados H3 #N"; HC's note holds the real name.
UPDATE "Event" SET "title" = 'BH3 41st Anniversary Bar Run', "updatedAt" = NOW() AT TIME ZONE 'UTC'
WHERE id = 'cmwe9txg4005h07jx2gy2te5y' AND "title" = '2358';

